-- BeeFitness PostgreSQL schema proposal. Do not apply without separate approval.
BEGIN;
CREATE TABLE IF NOT EXISTS bf_categories(id BIGSERIAL PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,slug VARCHAR(100) NOT NULL UNIQUE,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bf_products(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),sku VARCHAR(80) UNIQUE,name VARCHAR(140) NOT NULL,description TEXT NOT NULL DEFAULT '',category_id BIGINT REFERENCES bf_categories(id),price_halalas BIGINT NOT NULL CHECK(price_halalas>0),compare_at_halalas BIGINT CHECK(compare_at_halalas IS NULL OR compare_at_halalas>0),stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0),image_url TEXT,active BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bf_orders(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),reference_id VARCHAR(100) NOT NULL UNIQUE,customer_name VARCHAR(120) NOT NULL,customer_email VARCHAR(200) NOT NULL,customer_phone VARCHAR(30) NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'SAR',subtotal_halalas BIGINT NOT NULL CHECK(subtotal_halalas>=0),shipping_halalas BIGINT NOT NULL DEFAULT 0 CHECK(shipping_halalas>=0),total_halalas BIGINT NOT NULL CHECK(total_halalas>=0),status VARCHAR(32) NOT NULL DEFAULT 'pending',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bf_order_items(id BIGSERIAL PRIMARY KEY,order_id UUID NOT NULL REFERENCES bf_orders(id) ON DELETE RESTRICT,product_id UUID REFERENCES bf_products(id) ON DELETE SET NULL,product_name_snapshot VARCHAR(140) NOT NULL,sku_snapshot VARCHAR(80),quantity INTEGER NOT NULL CHECK(quantity>0),unit_price_halalas BIGINT NOT NULL CHECK(unit_price_halalas>0),line_total_halalas BIGINT NOT NULL CHECK(line_total_halalas>0));
CREATE TABLE IF NOT EXISTS bf_payment_attempts(id BIGSERIAL PRIMARY KEY,order_id UUID NOT NULL REFERENCES bf_orders(id) ON DELETE RESTRICT,provider VARCHAR(16) NOT NULL CHECK(provider IN('tabby','tamara')),provider_order_id VARCHAR(160),provider_payment_id VARCHAR(160),status VARCHAR(32) NOT NULL DEFAULT 'created',checkout_url TEXT,idempotency_key VARCHAR(160) NOT NULL UNIQUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bf_webhook_events(id BIGSERIAL PRIMARY KEY,provider VARCHAR(16) NOT NULL CHECK(provider IN('tabby','tamara')),provider_event_id VARCHAR(200) NOT NULL,event_type VARCHAR(100) NOT NULL,signature_verified BOOLEAN NOT NULL DEFAULT FALSE,payload JSONB NOT NULL,processing_status VARCHAR(24) NOT NULL DEFAULT 'received',received_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),processed_at TIMESTAMPTZ,UNIQUE(provider,provider_event_id));
CREATE INDEX IF NOT EXISTS bf_products_active_category_idx ON bf_products(active,category_id);
CREATE INDEX IF NOT EXISTS bf_orders_created_idx ON bf_orders(created_at DESC);
CREATE INDEX IF NOT EXISTS bf_payment_attempts_order_idx ON bf_payment_attempts(order_id,created_at DESC);
COMMIT;
